Rust/PyO3 example



Encoding


// Generate random permutation of N integers
let mut numbers: Vec&lt;usize&gt; = (0..N).collect();
let mut rng = thread_rng();
numbers.shuffle(&mut rng);
let permutation = numbers;

// Generate pairs for each z
let mut pairs = Vec::with_capacity(zs.len());
for &z in &zs {
    // Generate random x between 0 and N-1
    let x = rng.gen_range(0..N);

    // Compute y such that x - y = z (mod L)
    let y = if x &gt;= z {
        (x - z) % L
    } else {
        ((x + L) - z) % L
    };

    // Apply permutation to x and y
    let px = permutation[x];
    let py = permutation[y];
    pairs.push((px, py));

Rust/PyO3 example



Decoding


// Create inverse permutation
let mut inverse = vec![0; N];
for (i, &p) in permutation.iter().enumerate() {
    inverse[p] = i;
}

// Recover z for each pair
let mut zs = Vec::with_capacity(pairs.len());
for &(px, py) in pairs {
    // Apply inverse permutation to get x and y
    let x = inverse[px];
    let y = inverse[py];

    // Compute z = x - y (mod L)
    let z = if x &gt;= y {
        (x - y) % L
    } else {
        ((x + L) - y) % L
    };
    zs.push(z);
}

Numba
Either add engine="numba" parameter to Pandas functions, or add a @jit annotation to Python funcs.






WarningNumba-annotated code




import numba


@numba.jit
def f_numba(x):
    return x * (x - 1)


@numba.jit
def integrate_f_numba(a, b, N):
    s = 0
    dx = (b - a) / N
    for i in range(N):
        s += f_numba(a + i * dx)
    return s * dx


@numba.jit
def apply_integrate_f_numba(col_a, col_b, col_N):
    n = len(col_N)
    result = np.empty(n, dtype="float64")
    assert len(col_a) == len(col_b) == n
    for i in range(n):
        result[i] = integrate_f_numba(col_a[i], col_b[i], col_N[i])
    return result


def compute_numba(df):
    result = apply_integrate_f_numba(
        df["a"].to_numpy(), df["b"].to_numpy(), df["N"].to_numpy()
    )
    return pd.Series(result, index=df.index, name="result")









